/*
 * e1rufetch(1): system information card, e1 family style.
 */

#include "ulib.h"

/*
 * Hollow e1ruBSD wordmark, generated by:
 *   python3 tools/bigtext.py -f hollow "e1ruBSD"
 * All rows padded to the rendered width (51 columns) so the stat column
 * lines up; glyph bytes are unchanged.
 */
static const char *logo[] = {
	"        __                   ____    _____   ____  ",
	"       /_ |                 |  _ \\  / ____| |  _ \\ ",
	"  ___   | |  _ __   _   _   | |_| | | (___  | | | |",
	" / _ \\  | | | '__| | | | |  |  _ <   \\___ \\ | | | |",
	"|  __/  | | | |    | |_| |  | |_| |  ____)  | |_| |",
	" \\___|  |_| |_|     \\__,_|  |____/  |_____/ |____/ ",
	NULL
};

int
main(int argc, char **argv)
{
	struct utsname un;
	struct meminfo mi;

	(void)argc;
	(void)argv;
	uname(&un);
	meminfo(&mi);

	int i = 0;
	const char **l = logo;

	for (; *l; l++, i++) {
		printf("%s  ", *l);
		switch (i) {
		case 0:
			printf("%s %s (RUNE)", un.sysname, un.release);
			break;
		case 1:
			printf("arch: %s", un.machine);
			break;
		case 2:
			printf("uptime: %lu s", uptime_secs());
			break;
		case 3:
			printf("memory: %luM/%luM free",
			    mi.mi_total / (1024 * 1024),
			    mi.mi_free / (1024 * 1024));
			break;
		case 4:
			printf("shell: rsh");
			break;
		}
		printf("\n");
	}
	printf("e1 family -- POSIX-flavored BSD\n");
	return 0;
}
